// ── Register-return ABI variants (the trust re-emit) ────────────────────────
// The current self-hosted frontend returns pointer-sized values (Arc<Expr> /
// Box<Level>, each 8 B) in a register, `(this) -> ptr`, rather than through the
// older sret out-pointer `(sret, this) -> ()`. `bind_stitch_externs` picks the
// variant matching each leaf's emitted functy, so the frozen (sret) and regen
// (register) fixtures both bind faithfully off the SAME table.
//
// <Arc<Expr> as Clone>::clone: the raw Arc value is the ArcInner base
// (= data_ptr - 16, matching the +16 in ns_shim_arc_as_ref); `into_raw` keeps
// the strong count this clone just incremented.
extern "C" fn ns_shim_arc_clone_reg(
    this: *const std::sync::Arc<nslice::Expr>,
) -> *const nslice::Expr {
    unsafe {
        let data = std::sync::Arc::into_raw(std::sync::Arc::clone(&*this)) as *const u8;
        data.sub(16) as *const nslice::Expr
    }
}
// Box<Level>::new -> the boxed heap pointer (= the Box<Level> value).
extern "C" fn ns_shim_box_lvl_new_reg(value: *const nslice::Level) -> *const nslice::Level {
    unsafe {
        let v = std::ptr::read(value);
        Box::into_raw(Box::new(v)) as *const nslice::Level
    }
}
// <Box<Level> as Clone>::clone -> the cloned box's heap pointer.
extern "C" fn ns_shim_box_lvl_clone_reg(this: *const Box<nslice::Level>) -> *const nslice::Level {
    unsafe {
        let b: &Box<nslice::Level> = &*this;
        Box::into_raw(b.clone()) as *const nslice::Level
    }
}

// drop_glue / eh-personality leaves resolve to a no-op (the shims LEAK by
// design; nothing to free on the one-shot JIT path).
extern "C" fn ns_shim_noop_drop() {}
// A panic leaf firing would be a genuine divergence — abort rather than
// silently mis-execute.
extern "C" fn ns_shim_abort() {
    std::process::abort();
}

// ════════════════════════════════════════════════════════════════════════════
// Extern auto-binder: classify every EMPTY-BODY fn in the module by demangled
// substring and bind its faithful shim. Any unclassified leaf fails loudly.
// ════════════════════════════════════════════════════════════════════════════

fn collect_empty_leaves(tir: &str) -> Vec<String> {
    let lines: Vec<&str> = tir.lines().collect();
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < lines.len() {
        if let Some(rest) = lines[i].strip_prefix("fn @") {
            if let Some(name) = rest.split('(').next() {
                if i + 1 < lines.len() && lines[i + 1].trim() == "}" {
                    out.push(name.to_string());
                }
            }
        }
        i += 1;
    }
    out
}

/// Map every `fn @name(functy.N)` leaf to its resolved `functy.N = SIG`
/// signature string. Used to pick a shim's ABI variant (sret vs
/// register-return) from the EMITTED calling convention — the frozen (stable)
/// fixtures emit pointer-sized returns via sret `(ptr, ptr) -> ()`, the trust
/// re-emit via register-return `(ptr) -> (ptr)`, and this same binder serves
/// BOTH the register-return proj regen and the sret whnf-route frozen const on
/// the trust lane, so the choice must be per-leaf, not a global cfg.
fn leaf_signatures(tir: &str) -> HashMap<String, String> {
    let lines: Vec<&str> = tir.lines().collect();
    let mut sig_of_id: HashMap<&str, &str> = HashMap::new();
    for ln in &lines {
        if let Some(rest) = ln.strip_prefix("functy.") {
            if let Some((id, sig)) = rest.split_once('=') {
                sig_of_id.insert(id.trim(), sig.trim());
            }
        }
    }
    let mut out: HashMap<String, String> = HashMap::new();
    for ln in &lines {
        if let Some(rest) = ln.strip_prefix("fn @") {
            if let Some(paren) = rest.find("(functy.") {
                let name = &rest[..paren];
                let after = &rest[paren + "(functy.".len()..];
                if let Some(idend) = after.find(')') {
                    if let Some(sig) = sig_of_id.get(&after[..idend]) {
                        out.insert(name.to_string(), (*sig).to_string());
                    }
                }
            }
        }
    }
    out
}

fn bind_stitch_externs(tir: &str) -> HashMap<String, *const u8> {
    let empty_leaves = collect_empty_leaves(tir);
    let sigs = leaf_signatures(tir);
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert("__rust_alloc".to_string(), ns_shim_rust_alloc as *const u8);
    let mut unbound: Vec<String> = Vec::new();
    for sym in &empty_leaves {
        let s = sym.as_str();
        // Register-return ABI marker: the current frontend emits pointer-sized
        // returns (Arc<Expr>/Box<Level>, 8 B) as `(ptr) -> (ptr)` rather than the
        // older sret `(ptr, ptr) -> ()`. Detected from the EMITTED functy so the
        // same table binds the register-return regen and the sret frozen const.
        let is_reg_ret = sigs
            .get(sym)
            .map(|g| g.as_str() == "(ptr) -> (ptr)")
            .unwrap_or(false);
        let shim: Option<*const u8> =
        // drop_glue / eh-personality leaves -> no-op: the shims deliberately LEAK
        // on the one-shot JIT path, so nothing needs freeing. MUST precede the
        // Vec/Result/Option substring rules (drop_glue leaf names embed them).
        if s.contains("drop_glue") || s.contains("rust_eh_personality") {
            Some(ns_shim_noop_drop as *const u8)
        } else if s.contains("panic") {
            // A panic leaf firing is a genuine divergence — abort loudly.
            Some(ns_shim_abort as *const u8)
        } else if s.contains("3numm14saturating_add") {
            Some(ns_shim_sat_add as *const u8)
        } else if s.contains("3numm14saturating_sub") {
            Some(ns_shim_sat_sub as *const u8)
        } else if s.contains("3numj14saturating_add") {
            Some(ns_shim_sat_add_usize as *const u8)
        } else if s.contains("12wrapping_mul") {
            Some(ns_shim_wrap_mul as *const u8)
        } else if s.starts_with("_RNvYh") && s.contains("3Ord3max") {
            Some(ns_shim_max_u8 as *const u8)
        } else if s.starts_with("_RNvYh") && s.contains("3Ord3min") {
            Some(ns_shim_min_u8 as *const u8)
        } else if s.starts_with("_RNvYm") && s.contains("3Ord3max") {
            Some(ns_shim_max_u32 as *const u8)
        } else if s.starts_with("_RNvYm") && s.contains("3Ord3min") {
            Some(ns_shim_min_u32 as *const u8)
        } else if s.contains("5implsmNtB8_4Hash4hash") {
            Some(ns_shim_hash_u32 as *const u8)
        } else if s.contains("5implsyNtB8_4Hash4hash") {
            Some(ns_shim_hash_u64 as *const u8)
        } else if s.contains("5implsiNtB8_4Hash4hash") {
            Some(ns_shim_hash_i32 as *const u8)
        } else if s.contains("3BoxNt") && s.contains("5Level") && s.contains("4Hash4hash") {
            Some(ns_shim_hash_box_level as *const u8)
        } else if s.contains("4NameNtB7_9PartialEq2eq") {
            Some(ns_shim_name_eq as *const u8)
        }
        // DERIVED value-level Name::ne — MUST precede any `<&Name>::ne` match.
        else if s.starts_with("_RNvY") && s.contains("4Name") && s.contains("9PartialEq2ne") {
            Some(ns_shim_name_ne_val as *const u8)
        } else if s.contains("6FVarIdNtB7_9PartialEq2eq") {
            Some(ns_shim_fvarid_eq as *const u8)
        } else if s.contains("7LiteralNtB7_9PartialEq2eq") {
            Some(ns_shim_lit_eq as *const u8)
        } else if s.contains("5implsRmNtB7_9PartialEq2eq") {
            Some(ns_shim_u32ref_eq as *const u8)
        } else if s.contains("5implsRyNtB7_9PartialEq2eq") {
            Some(ns_shim_u64ref_eq as *const u8)
        } else if s.contains("5implsRbNtB7_9PartialEq2eq") {
            Some(ns_shim_boolref_eq as *const u8)
        }
        // Registry Vecs (reversed header): struct-element registries.
        else if s.contains("13InductiveInfoE") && s.contains("5Deref5deref") {
            Some(ns_shim_vec_reg_deref as *const u8)
        } else if s.contains("15ConstructorInfoE") && s.contains("5Deref5deref") {
            Some(ns_shim_vec_reg_deref as *const u8)
        } else if s.contains("13InductiveInfoE3new") {
            Some(ns_shim_vecreg_new as *const u8)
        } else if s.contains("15ConstructorInfoE3new") {
            Some(ns_shim_vecreg_new as *const u8)
        }
        // Registry pair-Vecs keyed by Name (env / ctor_np / decl_types /
        // ctor_types; reversed header for both inline-vec! and Vec::new).
        else if s.contains("3VecTNt") && s.contains("4Name") && s.contains("3new") {
            Some(ns_shim_vecreg_new as *const u8)
        } else if s.contains("3VecTNt") && s.contains("4Name") && s.contains("5Deref5deref") {
            Some(ns_shim_vecpair_deref_alias as *const u8)
        }
        // The [C3] cache assoc-lists Vec<(Expr, Expr)> — HOST layout
        // (constructed and touched exclusively through these shims).
        else if s.contains("3VecTNt") && s.contains("4Expr") && s.contains("3new") {
            Some(ns_shim_pairvec_new as *const u8)
        } else if s.contains("3VecTNt") && s.contains("4Expr") && s.contains("4push") {
            Some(ns_shim_pairvec_push as *const u8)
        } else if s.contains("3VecTNt") && s.contains("4Expr") && s.contains("3len") {
            Some(ns_shim_pairvec_len as *const u8)
        } else if s.contains("3VecTNt") && s.contains("4Expr") && s.contains("5index") {
            Some(ns_shim_pairvec_index as *const u8)
        }
        // Vec<Expr> ops (host layout).
        else if s.contains("3VecNt") && s.contains("4ExprE3new") {
            Some(ns_shim_vec_new as *const u8)
        } else if s.contains("3VecNt") && s.contains("4ExprE3len") {
            Some(ns_shim_vec_len as *const u8)
        } else if s.contains("3VecNt") && s.contains("4ExprE4push") {
            Some(ns_shim_vec_push as *const u8)
        } else if s.contains("3VecNt") && s.contains("4ExprE3pop") {
            Some(ns_shim_vec_pop as *const u8)
        } else if s.contains("3VecNt") && s.contains("4ExprE") && s.contains("5index") {
            Some(ns_shim_vec_index as *const u8)
        } else if s.contains("3VecNt") && s.contains("4ExprE") && s.contains("8DerefMut9deref_mut")
        {
            Some(ns_shim_vec_deref_mut as *const u8)
        } else if s.contains("3VecNt") && s.contains("4ExprE") && s.contains("5Deref5deref") {
            Some(ns_shim_vec_deref as *const u8)
        } else if s.contains("SNt") && s.contains("4Expr7reverse") {
            Some(ns_shim_reverse as *const u8)
        } else if s.contains("SNt") && s.contains("4Expr8is_empty") {
            Some(ns_shim_slice_is_empty as *const u8)
        }
        // Vec<Level> ops (host layout).
        else if s.contains("3VecNt") && s.contains("5LevelE3new") {
            Some(ns_shim_vec_lvl_new as *const u8)
        } else if s.contains("3VecNt") && s.contains("5LevelE3len") {
            Some(ns_shim_vec_lvl_len as *const u8)
        } else if s.contains("3VecNt") && s.contains("5LevelE4push") {
            Some(ns_shim_vec_lvl_push as *const u8)
        } else if s.contains("3VecNt") && s.contains("5LevelE") && s.contains("Clone5clone") {
            Some(ns_shim_vec_lvl_clone as *const u8)
        } else if s.contains("3VecNt") && s.contains("5LevelE") && s.contains("5Deref5deref") {
            Some(ns_shim_vec_lvl_deref as *const u8)
        }
        // Box<Level> ops (new/clone drifted sret -> register across toolchains).
        else if s.contains("3BoxNt") && s.contains("5LevelE3new") {
            Some(if is_reg_ret {
                ns_shim_box_lvl_new_reg as *const u8
            } else {
                ns_shim_box_lvl_new as *const u8
            })
        } else if s.contains("3BoxNt") && s.contains("5LevelE") && s.contains("Clone5clone") {
            Some(if is_reg_ret {
                ns_shim_box_lvl_clone_reg as *const u8
            } else {
                ns_shim_box_lvl_clone as *const u8
            })
        }
        // Arc<Expr> ops (clone drifted sret -> register across toolchains).
        else if s.contains("3ArcNt") && s.contains("4ExprE") && s.contains("5AsRef") {
            Some(ns_shim_arc_as_ref as *const u8)
        } else if s.contains("3ArcNt") && s.contains("4ExprE") && s.contains("Clone5clone") {
            Some(if is_reg_ret {
                ns_shim_arc_clone_reg as *const u8
            } else {
                ns_shim_arc_clone as *const u8
            })
        }
        // Option<Expr>::clone.
        else if s.contains("6OptionNt")
            && s.contains("4ExprE")
            && s.contains("5clone5Clone5clone")
        {
            Some(ns_shim_opt_clone as *const u8)
        }
        // Result<T, TypeError> ? operator — bool (is_prop, THE GATE),
        // unit (the batch fills), Expr (inference). b/u before Nt.
        else if s.contains("6Resultb") && s.contains("9TypeError") && s.contains("3Try6branch") {
            Some(ns_shim_result_bool_branch as *const u8)
        } else if s.contains("6Resultb")
            && s.contains("9TypeError")
            && s.contains("13from_residual")
        {
            Some(ns_shim_result_bool_from_residual as *const u8)
        } else if s.contains("6Resultu") && s.contains("9TypeError") && s.contains("3Try6branch") {
            Some(ns_shim_result_unit_branch as *const u8)
        } else if s.contains("6Resultu")
            && s.contains("9TypeError")
            && s.contains("13from_residual")
        {
            Some(ns_shim_result_unit_from_residual as *const u8)
        } else if s.contains("6ResultNt")
            && s.contains("4Expr")
            && s.contains("9TypeError")
            && s.contains("3Try6branch")
        {
            Some(ns_shim_result_expr_branch as *const u8)
        } else if s.contains("6ResultNt")
            && s.contains("4Expr")
            && s.contains("9TypeError")
            && s.contains("13from_residual")
        {
            Some(ns_shim_result_expr_from_residual as *const u8)
        }
        // core::ptr::write::<Expr> (the roots' out-writes).
        else if s.contains("3ptr5write") && s.contains("4Expr") {
            Some(ns_shim_ptr_write_expr as *const u8)
        } else {
            None
        };
        match shim {
            Some(p) => {
                externs.insert(sym.clone(), p);
            }
            None => unbound.push(sym.clone()),
        }
    }
    assert!(
        unbound.is_empty(),
        "unbound extern leaves (need shims): {unbound:#?}"
    );
    assert_eq!(
        externs.len(),
        empty_leaves
            .iter()
            .collect::<std::collections::HashSet<_>>()
            .len()
            + 1,
        "every distinct empty-body leaf must be bound (plus __rust_alloc)"
    );
    externs
}

// alias so pair-Vec deref shares the element-agnostic reversed-header reader.
extern "C" fn ns_shim_vecpair_deref_alias(sret: *mut (*const u8, usize), this: *const [usize; 3]) {
    ns_shim_vec_reg_deref(sret, this)
}

// ════════════════════════════════════════════════════════════════════════════
// THE GATE-SWALLOWING CORRUPTED ORACLE (the pre-#2208 bug, resurrected):
// byte-for-byte the strict infer_proj_type_from_impl EXCEPT the two is_prop
// consults treat inference failure as "not Prop" (`.unwrap_or(false)`)
// instead of propagating with `?`. The gate tests prove this oracle DISAGREES
// with the JIT'd machine code — i.e., the compiled gate genuinely propagates.
// ════════════════════════════════════════════════════════════════════════════

fn gate_swallowing_infer_proj_strict(
    v: &nslice::CertVerifier,
    struct_name: nslice::Name,
    idx: u32,
    expr: &nslice::Expr,
    expr_type: &nslice::Expr,
    caches: &mut nslice::TcCaches,
) -> Result<nslice::Expr, nslice::TypeError> {
    use nslice::{Expr, ExprKind, LevelVec, Name, TypeError, cache_get};
    let proj_expr = Expr::proj(struct_name, idx, expr.clone());
    if let Some(cached) = cache_get(&caches.proj, &proj_expr) {
        return Ok(cached);
    }
    let expr_type_whnf = v.whnf_impl(expr_type, caches);
    // THE SWALLOW — precisely the bug the real line-95 `?` gate fixes:
    let is_prop_type = v.is_prop(&expr_type_whnf, caches).unwrap_or(false);
    let (type_name, type_levels): (Name, LevelVec) = match &expr_type_whnf.get_app_fn().kind {
        ExprKind::Const(name, levels) => (*name, levels.clone()),
        _ => return Err(TypeError::InvalidProjNotStruct),
    };
    if type_name != struct_name {
        return Err(TypeError::InvalidProjNotStruct);
    }
    let type_args = expr_type_whnf.get_app_args();
    let ind_val = match v.get_inductive(&struct_name) {
        Some(i) => i,
        None => return Err(TypeError::UnknownInductive(struct_name)),
    };
    if ind_val.num_ctors != 1 {
        return Err(TypeError::InvalidProjNotUniqueConstructor(struct_name));
    }
    let ctor_name = ind_val.ctor_name;
    let ctor_val = match v.get_constructor(&ctor_name) {
        Some(c) => c,
        None => return Err(TypeError::UnknownConst(ctor_name)),
    };
    if idx >= ctor_val.num_fields {
        return Err(TypeError::InvalidProjIndexOutOfBounds(
            idx,
            ctor_val.num_fields,
        ));
    }
    if !type_levels.is_empty() {
        return Err(TypeError::LevelCountMismatch(struct_name));
    }
    let ctor_type = match v.ctor_declared_type(&ctor_name) {
        Some(t) => t,
        None => return Err(TypeError::UnknownConst(ctor_name)),
    };
    let num_params = ctor_val.num_params as usize;
    let num_indices = ind_val.num_indices as usize;
    let expected_args = num_params + num_indices;
    if type_args.len() != expected_args {
        return Err(TypeError::InvalidProjWrongArgCount(
            type_args.len() as u32,
            expected_args as u32,
        ));
    }
    let instantiated_ctor_type =
        v.instantiate_params_prefix(&ctor_type, &type_args, num_params, caches);
    if !is_prop_type {
        v.cache_projection_field_types_non_prop(
            &struct_name,
            expr,
            &instantiated_ctor_type,
            ctor_val.num_fields,
            caches,
        )?;
        if let Some(cached) = cache_get(&caches.proj, &proj_expr) {
            return Ok(cached);
        }
        return Err(TypeError::InvalidProjIndexOutOfBounds(
            idx,
            ctor_val.num_fields,
        ));
    }
    gate_swallowing_prop_batch(
        v,
        &struct_name,
        expr,
        &instantiated_ctor_type,
        ctor_val.num_fields,
        caches,
    )?;
    if let Some(cached) = cache_get(&caches.proj, &proj_expr) {
        return Ok(cached);
    }
    Err(TypeError::InvalidProjIndexOutOfBounds(
        idx,
        ctor_val.num_fields,
    ))
}

fn gate_swallowing_prop_batch(
    v: &nslice::CertVerifier,
    struct_name: &nslice::Name,
    expr: &nslice::Expr,
    instantiated_ctor_type: &nslice::Expr,
    num_fields: u32,
    caches: &mut nslice::TcCaches,
) -> Result<(), nslice::TypeError> {
    use nslice::{Expr, TypeError, cache_insert};
    let mut current_type = instantiated_ctor_type.clone();
    let mut field_idx: u32 = 0;
    while field_idx < num_fields {
        let (domain, body) = match v.pi_domain_body_quick(&current_type, caches) {
            Some(db) => db,
            None => {
                return Err(TypeError::InvalidProjIndexOutOfBounds(
                    num_fields.saturating_sub(1),
                    field_idx,
                ));
            }
        };
        // THE SWALLOW at the per-field validation site (the second real gate).
        let dom_in_prop = v.is_prop(&domain, caches).unwrap_or(false);
        if !dom_in_prop {
            return Err(TypeError::InvalidProjFromProp(field_idx));
        }
        let proj_expr = Expr::proj(*struct_name, field_idx, expr.clone());
        if field_idx + 1 < num_fields {
            if body.has_loose_bvars() {
                current_type = body.instantiate(&proj_expr);
            } else {
                current_type = body;
            }
        }
        cache_insert(&mut caches.proj, proj_expr, domain);
        field_idx += 1;
    }
    Ok(())
}

/// Fresh registries + verifier + caches for driving the swallowing oracle
/// natively (the same tables the roots build internally).
struct OracleTables {
    ctor_np: Vec<(nslice::Name, u32)>,
    decl_types: Vec<(nslice::Name, nslice::Expr)>,
    ctor_types: Vec<(nslice::Name, nslice::Expr)>,
    inductives: Vec<nslice::InductiveInfo>,
    ctors: Vec<nslice::ConstructorInfo>,
    env: Vec<(nslice::Name, Option<nslice::Expr>)>,
}
impl OracleTables {
    fn new() -> Self {
        OracleTables {
            ctor_np: nslice::build_ctor_np(),
            decl_types: nslice::build_decl_types(),
            ctor_types: nslice::build_ctor_types(),
            inductives: nslice::build_inductives(),
            ctors: nslice::build_ctors(),
            env: Vec::new(),
        }
    }
    fn verifier(&self) -> nslice::CertVerifier<'_> {
        nslice::CertVerifier {
            env: &self.env,
            ctor_np: &self.ctor_np,
            decl_types: &self.decl_types,
            ctor_types: &self.ctor_types,
            inductives: &self.inductives,
            ctors: &self.ctors,
        }
    }
}

// ════════════════════════════════════════════════════════════════════════════
// JIT plumbing
// ════════════════════════════════════════════════════════════════════════════

// Two frozen snapshots of `--mir-emit-closure tc_proj_root`, selected by exact
// fixture-compiler identity (see build.rs):
//   * Rust 1.95 (`MIR_TC_PROJ_CLOSURE_TRUST_IR` inline const above) — baked by
//     the fixtures' 1.95 generation toolchain: that build's repr(Rust) niche/
//     discriminant layout (the `Vec<(Name, Option<Expr>)>` env / `TypeError`
//     payload niches this proj closure exercises), and the older sret ABI
//     `(sret, this) -> ()` for the Arc<Expr>/Box<Level> clones and Box<Level>::new.
//   * Rust 1.97 (`clean_tc_stitch.trust.tir`) — re-emitted by the current self-hosted
//     frontend (prerelease rustc-master layout), abort profile
//     (`-C panic=abort -C overflow-checks=off -C debug-assertions=off`; 0 invoke,
//     matching the frozen generation profile). Three pointer-sized leaves drifted
//     ABI to register-return `(this) -> ptr`: Arc<Expr>::clone, Box<Level>::new,
//     Box<Level>::clone; the only other deltas are drop_glue leaves + drifted v0
//     disambiguators, both absorbed by `bind_stitch_externs` (drop_glue -> no-op,
//     shim ABI chosen per leaf from its emitted functy, content-substring binding).
// The tc_whnf_route fixture does NOT drift (its closure never touches those
// niches) and stays a single frozen const used on both lanes. Both lanes RUN all
// five tests — nothing is layout-gated to `ignore`.
#[cfg(kernel_fixture_layout_matches)]
const PROJ_TIR: &str = MIR_TC_PROJ_CLOSURE_TRUST_IR;
#[cfg(not(kernel_fixture_layout_matches))]
const PROJ_TIR: &str = include_str!("clean_tc_stitch.trust.tir");

/// ABI of the MIR-emitted tc_proj_root: (out, err_payload_out, lens, scenario, entry) -> i32.
type ProjFn = extern "C" fn(*mut nslice::Expr, *mut u64, *mut u64, u32, u32) -> i32;
/// ABI of the MIR-emitted tc_whnf_route_root: (out, lens, scenario) -> i32.
type WhnfFn = extern "C" fn(*mut nslice::Expr, *mut u64, u32) -> i32;

fn jit_proj_module() -> (trust_cg_codegen::jit::ExecutableBuffer, ProjFn) {
    let module = trust_ir::parser::parse_module(PROJ_TIR)
        .expect("MIR-emitted tc_proj closure trust-ir text must parse");

    // CONFIRM the stitched machinery is genuinely IN-MODULE (real bodies).
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    assert!(
        bodied("CertVerifier____env___infer_proj_type_from_impl"),
        "the projection-typing impl (incl. THE GATE) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___is_prop"),
        "is_prop (whnf-infer-whnf-Sort0) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___cache_projection_field_types_non_prop"),
        "the non-Prop batch fill must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___cache_projection_field_types_prop"),
        "the Prop-validating batch fill (2nd gate site) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___walk_prop_telescope_to_idx"),
        "the quick-path telescope walk must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___instantiate_params_prefix"),
        "instantiate_params must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___pi_domain_body_quick"),
        "pi_domain_body_quick must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___infer_type_core"),
        "the VERIFIED infer pillar must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___whnf_inner")
            && bodied("CertVerifier____env___whnf_outer_loop"),
        "the CACHED whnf routing must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___whnf_core_inner")
            && bodied("CertVerifier____env___whnf_recurse"),
        "the whnf_core trampoline + core-cache routing must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___unfold_definition_cached"),
        "the m_unfold cache routing must be in-module"
    );
    assert!(
        bodied("cache_get") && bodied("cache_insert"),
        "the [C3] cache model must be in-module"
    );
    assert!(
        bodied("expr_eq") && bodied("kind_eq"),
        "the REAL Expr::eq cache-key discipline must be in-module"
    );
    assert!(
        bodied("err_code") && bodied("err_payload"),
        "the Err-identity packers must be in-module"
    );
    assert!(
        PROJ_TIR.contains("heap_alloc rust_heap"),
        "Arc::new must lower to heap_alloc (not stubbed)"
    );

    let externs = bind_stitch_externs(PROJ_TIR);
    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of MIR-emitted tc_proj closure failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("tc_proj_root")
        .expect("JIT symbol `tc_proj_root` not found")
        .as_ptr();
    // SAFETY: machine code for the (ptr, ptr, ptr, u32, u32) -> i32 ABI; buffer stays live.
    let f: ProjFn = unsafe { std::mem::transmute(raw) };
    (buffer, f)
}

fn jit_whnf_module() -> (trust_cg_codegen::jit::ExecutableBuffer, WhnfFn) {
    let module = trust_ir::parser::parse_module(MIR_TC_WHNF_ROUTE_CLOSURE_TRUST_IR)
        .expect("MIR-emitted tc_whnf_route closure trust-ir text must parse");

    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    assert!(
        bodied("CertVerifier____env___whnf"),
        "the whnf entry must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___whnf_impl"),
        "whnf_impl (already-normal kind gate) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___whnf_inner"),
        "whnf_inner (the whnf_cache routing) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___whnf_outer_loop"),
        "whnf_outer_loop (mid-loop consult) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___whnf_core_inner"),
        "the whnf_core trampoline must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___whnf_core_no_delta"),
        "whnf_core_no_delta (m_whnf_core discipline) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___whnf_recurse"),
        "whnf_recurse (core-cache read/write split) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___beta_or_iota_step"),
        "beta_or_iota_step (multi-arg beta) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___reduce_proj_with_mode"),
        "reduce_proj (cross-mode escalation) must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___try_unfold_definition"),
        "try_unfold_definition must be in-module"
    );
    assert!(
        bodied("CertVerifier____env___unfold_definition_cached"),
        "the m_unfold cache routing must be in-module"
    );
    assert!(
        bodied("cache_get") && bodied("cache_insert"),
        "the [C3] cache model must be in-module"
    );
    assert!(
        bodied("expr_eq") && bodied("kind_eq"),
        "the REAL Expr::eq cache-key discipline must be in-module"
    );
    assert!(
        bodied("Expr__instantiate_rev"),
        "instantiate_rev (multi-arg beta substitution) must be in-module"
    );
    assert!(
        MIR_TC_WHNF_ROUTE_CLOSURE_TRUST_IR.contains("heap_alloc rust_heap"),
        "Arc::new must lower to heap_alloc (not stubbed)"
    );

    let externs = bind_stitch_externs(MIR_TC_WHNF_ROUTE_CLOSURE_TRUST_IR);
    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of MIR-emitted tc_whnf_route closure failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("tc_whnf_route_root")
        .expect("JIT symbol `tc_whnf_route_root` not found")
        .as_ptr();
    // SAFETY: machine code for the (ptr, ptr, u32) -> i32 ABI; buffer stays live.
    let f: WhnfFn = unsafe { std::mem::transmute(raw) };
    (buffer, f)
}

fn jit_run_proj(f: ProjFn, scenario: u32, entry: u32) -> (i32, u64, u64, Option<nslice::Expr>) {
    let mut slot = std::mem::MaybeUninit::<nslice::Expr>::uninit();
    let mut payload: u64 = 0xDEAD;
    let mut lens: u64 = 0;
    // SAFETY: on ret==1 the JIT'd root has ptr::write'n a fully-initialized
    // Expr through the out pointer (children are heap_alloc'd ArcInner blocks,
    // data @ +16 — identical layout to native Arc).
    let code = f(slot.as_mut_ptr(), &mut payload, &mut lens, scenario, entry);
    let e = if code == 1 {
        Some(unsafe { slot.assume_init() })
    } else {
        None
    };
    (code, payload, lens, e)
}

fn jit_run_whnf(f: WhnfFn, scenario: u32) -> (i32, u64, nslice::Expr) {
    let mut slot = std::mem::MaybeUninit::<nslice::Expr>::uninit();
    let mut lens: u64 = 0;
    let ret = f(slot.as_mut_ptr(), &mut lens, scenario);
    // SAFETY: the whnf root always writes the result (ret is 1 or 2).
    (ret, lens, unsafe { slot.assume_init() })
}

// ════════════════════════════════════════════════════════════════════════════
// Test 1 — target (1): the is_prop ERR-PROPAGATION GATE surfaces identically.
// ════════════════════════════════════════════════════════════════════════════

/// THE GATE (tc/infer_proj.rs:95 + the second site at :329): every Err path of
/// the projection-typing surface must surface IDENTICALLY (code + payload +
/// cache-record effects) in native Rust and in the JIT'd machine code — in
/// particular the two genuine inference-Err propagation paths (GHOST: the
/// struct's own type undeclared; BADPROP2: a Prop field's type undeclared),
/// which a gate-swallowing checker would NOT produce. The corrupted oracle
/// (the pre-#2208 `.unwrap_or(false)` bug) must DISAGREE with the JIT on both.
#[test]
fn mir_tc_infer_proj_gate_err_propagation_roundtrip() {
    let (buffer, f) = jit_proj_module();

    // (scenario, strict code, strict payload, quick code, label)
    let cases: Vec<(u32, i32, u64, i32, &str)> = vec![
        (
            2,
            -9,
            0x5_0000_0002,
            0,
            "idx 5 of 2-field Point -> InvalidProjIndexOutOfBounds(5,2)",
        ),
        (
            3,
            -2,
            nslice::GHOST as u64,
            0,
            "THE GATE: GHOST's type undeclared -> is_prop Err(UnknownConst(GHOST)) PROPAGATES",
        ),
        (
            6,
            -6,
            0,
            0,
            "p : Point projected as DStruct -> InvalidProjNotStruct (name mismatch)",
        ),
        (
            9,
            -6,
            0,
            0,
            "x : Prop (type head Sort, not Const) -> InvalidProjNotStruct",
        ),
        (
            10,
            -2,
            nslice::GHOSTQ as u64,
            1,
            "GATE 2: Prop-batch field type GHOSTQ undeclared -> Err(UnknownConst(GHOSTQ)) PROPAGATES (quick path walks and ACCEPTS)",
        ),
        (
            12,
            -11,
            0x1,
            0,
            "pp0 : PPair unapplied -> InvalidProjWrongArgCount(0,1)",
        ),
        (
            13,
            -7,
            nslice::FAKE as u64,
            0,
            "FAKE declared but no inductive entry -> UnknownInductive",
        ),
        (
            14,
            -8,
            nslice::BOOLLIKE as u64,
            0,
            "BoolLike has 2 ctors -> InvalidProjNotUniqueConstructor",
        ),
        (
            15,
            -2,
            nslice::CTORLESS_MK as u64,
            0,
            "CtorLess's ctor missing from registry -> UnknownConst(ctor)",
        ),
        (
            16,
            -10,
            nslice::PBOXL as u64,
            0,
            "leveled type head PBoxL.{1} -> LevelCountMismatch ([C2] degenerate gate)",
        ),
    ];
    for (s, want_code, want_payload, want_quick, label) in &cases {
        let (nc, np, nl, _) = nslice::run_proj(*s, 0);
        assert_eq!(
            nc, *want_code,
            "native oracle strict code wrong on `{label}`"
        );
        assert_eq!(
            np, *want_payload,
            "native oracle strict payload wrong on `{label}`"
        );
        let (jc, jp, jl, _) = jit_run_proj(f, *s, 0);
        assert_eq!(
            jc, nc,
            "JIT strict code disagrees with native on `{label}`: native={nc} jit={jc}"
        );
        assert_eq!(
            jp, np,
            "JIT strict Err PAYLOAD disagrees with native on `{label}`: native={np:#x} jit={jp:#x}"
        );
        assert_eq!(
            jl, nl,
            "JIT strict cache-record effects (packed lens) disagree on `{label}`: native={nl:#x} jit={jl:#x}"
        );
        // quick path: the same impl with validate_prop_projection=false and
        // `.ok()` — Err collapses to None (ret 0) EXCEPT where the quick path
        // genuinely diverges (scenario 10: the walk skips Prop validation).
        let (nqc, _nqp, nql, nqe) = nslice::run_proj(*s, 1);
        assert_eq!(
            nqc, *want_quick,
            "native oracle quick code wrong on `{label}`"
        );
        let (jqc, _jqp, jql, jqe) = jit_run_proj(f, *s, 1);
        assert_eq!(
            jqc, nqc,
            "JIT quick code disagrees with native on `{label}`"
        );
        assert_eq!(jql, nql, "JIT quick lens disagree on `{label}`");
        match (&nqe, &jqe) {
            (Some(ne), Some(je)) => assert!(
                nslice::deep_eq(ne, je),
                "JIT quick result Expr disagrees on `{label}`"
            ),
            (None, None) => {}
            _ => panic!("quick result presence disagrees on `{label}`"),
        }
    }

    // ── NEGATIVE CONTROL 1 (the gate, swallowed): the pre-#2208 oracle on the
    // GHOST scenario ACCEPTS with Ok(Nat) — the JIT must DISAGREE (Err -2 with
    // payload GHOST). If the JIT'd gate ever swallowed the inference error,
    // it would agree with this corrupted oracle and this test would fail.
    let tables = OracleTables::new();
    let v = tables.verifier();
    let mut caches = nslice::caches_new();
    let g_expr = nslice::c(nslice::G_VAL);
    let g_type = v
        .infer_type(&g_expr, &mut caches)
        .expect("g's declared type must infer");
    let swallowed = gate_swallowing_infer_proj_strict(
        &v,
        nslice::Name(nslice::GHOST),
        0,
        &g_expr,
        &g_type,
        &mut caches,
    )
    .expect("the gate-SWALLOWING oracle must ACCEPT the GHOST projection (that is the bug)");
    assert!(
        nslice::deep_eq(&swallowed, &nslice::c(nslice::NATTY)),
        "the swallowing oracle must type GHOST.0 as Nat (the un-gated field type)"
    );
    let (jit_g_code, jit_g_payload, _, _) = jit_run_proj(f, 3, 0);
    assert_eq!(
        jit_g_code, -2,
        "the JIT'd gate MUST propagate the inference Err (not swallow like the corrupted oracle)"
    );
    assert_eq!(
        jit_g_payload,
        nslice::GHOST as u64,
        "the propagated Err must carry the GHOST name"
    );

    // ── NEGATIVE CONTROL 2 (the SECOND gate site, swallowed): on BADPROP2 the
    // swallowing oracle mis-reports InvalidProjFromProp(0) (-12); the real
    // propagation is UnknownConst(GHOSTQ) (-2). The JIT must match the real.
    let mut caches2 = nslice::caches_new();
    let bp2_expr = nslice::c(nslice::BP2_VAL);
    let bp2_type = v
        .infer_type(&bp2_expr, &mut caches2)
        .expect("bp2's declared type must infer");
    let swallowed2 = gate_swallowing_infer_proj_strict(
        &v,
        nslice::Name(nslice::BADPROP2),
        0,
        &bp2_expr,
        &bp2_type,
        &mut caches2,
    );
    let swallowed2_code = match &swallowed2 {
        Ok(_) => 1,
        Err(e) => nslice::err_code(e),
    };
    assert_eq!(
        swallowed2_code, -12,
        "the swallowing oracle must mis-classify the undeclared Prop field as InvalidProjFromProp"
    );
    let (jit_b_code, jit_b_payload, _, _) = jit_run_proj(f, 10, 0);
    assert_eq!(
        jit_b_code, -2,
        "the JIT'd 2nd gate site MUST propagate the inference Err"
    );
    assert_eq!(
        jit_b_payload,
        nslice::GHOSTQ as u64,
        "the propagated Err must carry the GHOSTQ name"
    );
    assert_ne!(
        jit_b_code, swallowed2_code,
        "the JIT must DISAGREE with the gate-swallowing oracle"
    );

    // Cross-scenario Err-identity distinctness: a constant-code/payload stub
    // cannot satisfy the suite (codes -2/-6/-7/-8/-9/-10/-11 all appear, and
    // the -2 payloads differ: GHOST vs GHOSTQ vs CTORLESS_MK).
    assert_ne!(nslice::GHOST, nslice::GHOSTQ);
    assert_ne!(
        jit_run_proj(f, 3, 0).1,
        jit_run_proj(f, 10, 0).1,
        "distinct gate payloads must stay distinct in the JIT"
    );

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// Test 2 — target (1): the Ok paths (batch fills, quick walk, dependent
// telescope, params>0, poisoned proj cache) native == JIT.
// ════════════════════════════════════════════════════════════════════════════

/// The projection-typing Ok surface: non-Prop batch fill (both entries share
/// it), the strict Prop batch vs quick walk divergence (BADPROP: strict
/// rejects with InvalidProjFromProp, quick ACCEPTS — the real
/// validate_prop_projection routing), the DEPENDENT telescope (field 1's type
/// mentions Proj(0)), params>0 instantiation, and the POISONED proj cache
/// (the top-of-impl consult must return the poison in machine code).
#[test]
fn mir_tc_infer_proj_ok_paths_roundtrip() {
    let (buffer, f) = jit_proj_module();

    // (scenario, entry, expected Expr, label)
    let natty = nslice::c(nslice::NATTY);
    let propq = nslice::c(nslice::PROPQ);
    let dep = nslice::ap(
        nslice::c(nslice::PBOX),
        nslice::pj(nslice::DSTRUCT, 0, nslice::c(nslice::D_VAL)),
    );
    let poison = nslice::c(nslice::POISON);
    let ok_cases: Vec<(u32, u32, &nslice::Expr, &str)> = vec![
        (0, 0, &natty, "Point.0 : Nat (strict, non-Prop batch)"),
        (
            0,
            1,
            &natty,
            "Point.0 : Nat (quick shares the non-Prop batch)",
        ),
        (1, 0, &natty, "Point.1 : Nat (strict)"),
        (1, 1, &natty, "Point.1 : Nat (quick)"),
        (
            4,
            0,
            &propq,
            "PROPS.1 : PROPQ (strict Prop batch, both fields validated)",
        ),
        (4, 1, &propq, "PROPS.1 : PROPQ (quick UNCACHED walk)"),
        (
            5,
            1,
            &natty,
            "BADPROP.0 : Nat via QUICK (skips Prop validation — real divergence)",
        ),
        (
            7,
            0,
            &dep,
            "DStruct.1 : PBox (DStruct.0 d) (strict, DEPENDENT instantiation)",
        ),
        (7, 1, &dep, "DStruct.1 : PBox (DStruct.0 d) (quick)"),
        (
            8,
            0,
            &natty,
            "PPair.1 : Nat (params>0 prefix instantiation, strict)",
        ),
        (8, 1, &natty, "PPair.1 : Nat (params>0, quick)"),
        (
            11,
            0,
            &poison,
            "POISONED proj cache: strict returns the poison (consult observed)",
        ),
        (
            11,
            1,
            &poison,
            "POISONED proj cache: quick returns the poison",
        ),
    ];
    for (s, entry, want, label) in &ok_cases {
        let (nc, np, nl, ne) = nslice::run_proj(*s, *entry);
        assert_eq!(nc, 1, "native oracle must be Ok on `{label}`");
        assert_eq!(np, 0, "native payload must be clear on `{label}`");
        let ne = ne.expect("native Ok expr");
        assert!(
            nslice::deep_eq(&ne, want),
            "native oracle shape wrong on `{label}`:\n  native = {ne:?}\n  want = {want:?}"
        );
        let (jc, jp, jl, je) = jit_run_proj(f, *s, *entry);
        assert_eq!(jc, 1, "JIT must be Ok on `{label}`");
        assert_eq!(jp, 0, "JIT payload must be clear on `{label}`");
        let je = je.expect("JIT Ok expr");
        // STRUCTURAL + ExprMeta word BIT-IDENTICAL at every node.
        assert!(
            nslice::deep_eq(&ne, &je),
            "MIR-emitted JIT disagrees with native on `{label}`:\n  native = {ne:?}\n  jit    = {je:?}"
        );
        assert_eq!(
            jl, nl,
            "JIT cache-record effects (packed lens) disagree on `{label}`: native={nl:#x} jit={jl:#x}"
        );
    }

    // The strict/quick divergence on scenario 5 is REAL in machine code: the
    // strict entry must reject BADPROP.0 with InvalidProjFromProp(0).
    let (jc5s, jp5s, _, _) = jit_run_proj(f, 5, 0);
    assert_eq!(
        jc5s, -12,
        "strict BADPROP.0 must reject via the Prop-validating batch (JIT)"
    );
    assert_eq!(jp5s, 0, "InvalidProjFromProp field_idx 0");
    let (nc5s, _, _, _) = nslice::run_proj(5, 0);
    assert_eq!(
        nc5s, jc5s,
        "strict/quick divergence must agree native == JIT"
    );

    // The batch-vs-walk cache discipline (packed lens: proj<<48|whnf<<32|
    // core<<16|unfold): strict s4 batch-fills BOTH fields (proj len 2); the
    // quick walk fills NOTHING (proj len 0). Verified on BOTH sides above via
    // lens equality; here assert the absolute discipline.
    let (_, _, nl4s, _) = nslice::run_proj(4, 0);
    let (_, _, nl4q, _) = nslice::run_proj(4, 1);
    assert_eq!(nl4s >> 48, 2, "strict Prop batch must cache both fields");
    assert_eq!(nl4q >> 48, 0, "quick Prop walk must cache nothing");
    let (_, _, jl4s, _) = jit_run_proj(f, 4, 0);
    let (_, _, jl4q, _) = jit_run_proj(f, 4, 1);
    assert_eq!(jl4s, nl4s, "JIT strict-batch record effects");
    assert_eq!(jl4q, nl4q, "JIT quick-walk record effects");

    // ── NEGATIVE CONTROLS (fail-loud) ──
    // 1) the meta-word comparison is ARMED: flip one bit of the JIT s7 result's
    //    top-level meta word (Expr layout: kind @0 (32B), meta u64 @32 — the
    //    layout every prior rung documents) and the deep compare MUST fail.
    let (_, _, _, je7) = jit_run_proj(f, 7, 0);
    let je7 = je7.expect("jit s7 Some");
    let (_, _, _, ne7) = nslice::run_proj(7, 0);
    let ne7 = ne7.expect("native s7 Some");
    let mut corrupted = je7.clone();
    unsafe {
        let meta_ptr = (&mut corrupted as *mut nslice::Expr as *mut u8).add(32) as *mut u64;
        *meta_ptr ^= 1;
    }
    assert!(
        !nslice::deep_eq(&ne7, &corrupted),
        "negative control: a single flipped meta bit MUST break the deep comparison"
    );
    // 2) the poison consult is not vacuous: the poison differs from the true
    //    field type, so a cache-skipping (always-recompute) implementation
    //    would return Nat on scenario 11 and fail the poison assert above.
    assert!(
        !nslice::deep_eq(&poison, &natty),
        "poison and true field type must differ"
    );
    // 3) distinct Ok shapes must not compare equal (the differential cannot
    //    be trivially true).
    assert!(
        !nslice::deep_eq(&natty, &dep),
        "distinct result shapes must differ"
    );

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// Test 3 — target (2): the whnf_cache routing (cold / warm / poisoned / the
// mid-loop delta-intermediate consult / the already-normal kind gate).
// ════════════════════════════════════════════════════════════════════════════

/// The cached whnf routing, observed through poison: a wrong cached value at
/// the root key (s2) and at the DELTA INTERMEDIATE key (s3, the beyond-Lean-4
/// mid-outer-loop consult, #3210) must be returned IDENTICALLY by native and
/// JIT — proving the machine code consults the whnf_cache at both sites. The
/// already-normal-kind gate (s4) must return BEFORE the (poisoned) cache; the
/// warm re-run (s1) must not grow any cache. Packed cache lengths
/// (proj<<48|whnf<<32|core<<16|unfold) are compared on every scenario.
#[test]
fn mir_tc_whnf_cache_routing_roundtrip() {
    let (buffer, f) = jit_whnf_module();

    let n0 = nslice::c(nslice::N0);
    let poison = nslice::c(nslice::POISON);
    let sent = nslice::c(nslice::SENT);
    let pi_term = nslice::Expr::pi(
        nslice::bd_default(),
        nslice::c(nslice::NATTY),
        nslice::c(nslice::NATTY),
    );

    // (scenario, want ret, want lens, want result, label)
    let cases: Vec<(u32, i32, u64, &nslice::Expr, &str)> = vec![
        (
            0,
            1,
            0x1_0001_0000,
            &n0,
            "COLD (lam x. x) n0: miss -> compute -> RECORD (whnf+core grow)",
        ),
        (
            1,
            1,
            0x1_0001_0000,
            &n0,
            "WARM double call: 2nd whnf is a pure cache HIT (identical result, NO growth)",
        ),
        (
            2,
            1,
            0x1_0000_0000,
            &poison,
            "POISONED root key: whnf_inner's consult returns the poison",
        ),
        (
            3,
            1,
            0x2_0000_0001,
            &sent,
            "POISONED delta intermediate: the MID-OUTER-LOOP consult (#3210) returns the sentinel",
        ),
        (
            4,
            1,
            0x1_0000_0000,
            &pi_term,
            "already-normal Pi + poisoned cache: the KIND GATE returns BEFORE the consult (poison NOT observed)",
        ),
    ];
    for (s, want_ret, want_lens, want, label) in &cases {
        let (nr, nl, ne) = nslice::run_whnf(*s);
        assert_eq!(nr, *want_ret, "native oracle ret wrong on `{label}`");
        assert_eq!(
            nl, *want_lens,
            "native oracle lens wrong on `{label}`: {nl:#x}"
        );
        assert!(
            nslice::deep_eq(&ne, want),
            "native oracle result wrong on `{label}`:\n  native = {ne:?}\n  want = {want:?}"
        );
        let (jr, jl, je) = jit_run_whnf(f, *s);
        assert_eq!(jr, nr, "JIT ret disagrees with native on `{label}`");
        assert_eq!(
            jl, nl,
            "JIT cache-record effects (packed lens) disagree on `{label}`: native={nl:#x} jit={jl:#x}"
        );
        assert!(
            nslice::deep_eq(&ne, &je),
            "MIR-emitted whnf JIT disagrees with native on `{label}`:\n  native = {ne:?}\n  jit    = {je:?}"
        );
    }

    // ── NEGATIVE CONTROLS (fail-loud) ──
    // 1) the poison is OBSERVED, not recomputed: a consult-skipping
    //    implementation would return the true whnf (n0) on s2 and disagree.
    let (_, _, je2) = jit_run_whnf(f, 2);
    assert!(
        nslice::deep_eq(&je2, &poison) && !nslice::deep_eq(&je2, &n0),
        "negative control: the s2 poison must be returned VERBATIM (cache consulted), never the recomputed n0"
    );
    // 2) the mid-loop consult is REAL: s3's key is the DELTA INTERMEDIATE
    //    (Const G), not the root (Const F) — an implementation checking only
    //    the entry key would compute through to G (stuck Const) instead of
    //    returning the sentinel.
    let (_, _, je3) = jit_run_whnf(f, 3);
    assert!(
        nslice::deep_eq(&je3, &sent) && !nslice::deep_eq(&je3, &nslice::c(nslice::GG)),
        "negative control: the s3 sentinel must surface via the MID-LOOP consult"
    );
    // 3) the kind gate is REAL: s4's cache is poisoned at the exact key, yet
    //    the already-normal Pi must be returned (an implementation consulting
    //    the cache before the kind gate would return the poison).
    let (_, _, je4) = jit_run_whnf(f, 4);
    assert!(
        nslice::deep_eq(&je4, &pi_term) && !nslice::deep_eq(&je4, &poison),
        "negative control: the already-normal kind gate must return BEFORE the poisoned cache"
    );
    // 4) warm != cold is observable through ret: scenario 1 returns 1 only if
    //    both calls agreed (a non-idempotent cache would return 2).
    let (jr1, _, _) = jit_run_whnf(f, 1);
    assert_eq!(jr1, 1, "warm re-run must agree with its own first result");

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// Test 4 — target (2): the whnf_core_cache write discipline, the unconditional
// core read, and the m_unfold cache.
// ════════════════════════════════════════════════════════════════════════════

/// The remaining cache disciplines: whnf_core_no_delta/whnf_recurse write the
/// core cache ONLY in full-proj mode (Lean 4 `!cheap_rec && !cheap_proj`,
/// s5); the core READ is unconditional even in cheap mode (#1768 — the s6
/// poison is observed through a cheap read); unfold_definition_cached caches
/// only successful unfolds and HITS on re-query (s7: the second whnf(G) grows
/// nothing); reduce_proj performs proj-iota field extraction after escalating
/// to full cached WHNF (s8); and the whnf_recurse write-gate POLARITY is pinned by the s9
/// CHEAP-ONLY probe (in s5 the full call re-creates the same key set and in
/// s6 the poisoned hit precedes the write, so ONLY s9 makes a write-on-cheap
/// bug at the whnf_recurse site observable: the core cache must stay EMPTY
/// and the lam-head key absent).
#[test]
fn mir_tc_whnf_core_unfold_discipline_roundtrip() {
    let (buffer, f) = jit_whnf_module();

    let n0 = nslice::c(nslice::N0);
    let poison = nslice::c(nslice::POISON);
    let hh = nslice::c(nslice::HH);

    let cases: Vec<(u32, i32, u64, &nslice::Expr, &str)> = vec![
        (
            5,
            1,
            0x2_0000,
            &n0,
            "core WRITE discipline: cheap_proj=true writes NOTHING, full-proj writes (2 entries: the beta term + the lam head)",
        ),
        (
            6,
            1,
            0x1_0000,
            &poison,
            "core READ is UNCONDITIONAL: the cheap read observes the poison (and writes nothing back)",
        ),
        (
            7,
            1,
            0x2_0000_0002,
            &hh,
            "m_unfold: whnf(F) unfolds F,G; whnf(G) re-queries G and HITS (no unfold growth)",
        ),
        (
            8,
            1,
            0x2_0002_0001,
            &n0,
            "reduce_proj: full-WHNF escalation reaches ctor-app and proj-iota extracts field 0",
        ),
        (
            9,
            1,
            0x0,
            &n0,
            "whnf_recurse write-gate POLARITY: the cheap-only run writes NOTHING (core EMPTY, lam-head scan clean)",
        ),
    ];
    for (s, want_ret, want_lens, want, label) in &cases {
        let (nr, nl, ne) = nslice::run_whnf(*s);
        assert_eq!(nr, *want_ret, "native oracle ret wrong on `{label}`");
        assert_eq!(
            nl, *want_lens,
            "native oracle lens wrong on `{label}`: {nl:#x}"
        );
        assert!(
            nslice::deep_eq(&ne, want),
            "native oracle result wrong on `{label}`:\n  native = {ne:?}\n  want = {want:?}"
        );
        let (jr, jl, je) = jit_run_whnf(f, *s);
        assert_eq!(jr, nr, "JIT ret disagrees with native on `{label}`");
        assert_eq!(
            jl, nl,
            "JIT cache-record effects disagree on `{label}`: native={nl:#x} jit={jl:#x}"
        );
        assert!(
            nslice::deep_eq(&ne, &je),
            "MIR-emitted whnf JIT disagrees with native on `{label}`:\n  native = {ne:?}\n  jit    = {je:?}"
        );
    }

    // ── NEGATIVE CONTROLS (fail-loud) ──
    // 1) s6: a write-on-cheap bug would leave core len 2 (poison + written
    //    result); the discipline demands EXACTLY the pre-seeded 1.
    let (_, jl6, je6) = jit_run_whnf(f, 6);
    assert_eq!(
        (jl6 >> 16) & 0xFFFF,
        1,
        "cheap-mode core read must NOT write back (poisoned entry stays the only one)"
    );
    assert!(
        nslice::deep_eq(&je6, &poison) && !nslice::deep_eq(&je6, &n0),
        "negative control: the cheap read must observe the poison, never recompute n0"
    );
    // 2) s7: ret==1 proves whnf(F) == whnf(G) (both reach H THROUGH the
    //    unfold cache hit); unfold len stuck at 2 proves only F and G were
    //    ever unfolded (the second query hit).
    let (jr7, jl7, _) = jit_run_whnf(f, 7);
    assert_eq!(jr7, 1, "whnf(F) and whnf(G) must agree (both H)");
    assert_eq!(jl7 & 0xFFFF, 2, "unfold cache must hold exactly F and G");
    // 3) s9: the whnf_recurse WRITE-GATE POLARITY is armed here and ONLY here
    //    (skeptic finding, closed): the cheap-only run must leave the core
    //    cache EMPTY. A write-on-cheap bug at the whnf_recurse site appends
    //    the lam-head key — a key NO other site writes in s9 — flipping the
    //    in-root scan to ret 2 and the core count to 1 (lens 0x1_0000); an
    //    unconditionally-writing whnf_core_no_delta instead appends the
    //    beta-term key (ret 1, lens 0x1_0000). Both native and JIT are pinned
    //    to the absolute discipline, not just to each other.
    let (jr9, jl9, je9) = jit_run_whnf(f, 9);
    assert_eq!(
        jr9, 1,
        "s9: the lam-head key must NOT be in the core cache after the cheap-only run (whnf_recurse write-on-cheap would append it)"
    );
    assert_eq!(
        jl9, 0x0,
        "s9: the cheap-only run must leave ALL caches empty (any core write is a discipline bug): {jl9:#x}"
    );
    assert!(
        nslice::deep_eq(&je9, &n0),
        "s9: cheap-mode beta must still reduce to n0"
    );
    let (nr9, nl9, _) = nslice::run_whnf(9);
    assert_eq!(
        (nr9, nl9),
        (1, 0x0),
        "s9: the native oracle must satisfy the same absolute discipline"
    );

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// Test 5 — backend regression: zext(load) used as a call argument.
// ════════════════════════════════════════════════════════════════════════════

/// Minimal reproducer for the backend defect found by the scenario-8
/// differential: a zero-extended loaded u32 used directly as an AArch64 call
/// argument must arrive as that u32 value, not as the surrounding 64-bit word.
const REPRO_ZEXT_LOAD_CALLARG_TRUST_IR: &str = r#"; TrustIr text format v1
module "repro::zext_load_callarg"

functy.0 = (u64, u64) -> (u64)

functy.1 = (ptr, u32) -> (u64)

fn @ext_add(functy.0) {
}

fn @repro_root(functy.1) {
bb0(%0: ptr, %1: u32):
    %10 = alloca (i32, i32), align 4
    %11 = load i64, ptr %0
    store i64 %11, ptr %10
    %12 = const i64 4
    %13 = gep i8, ptr %10, %12
    %14 = load u32, ptr %13
    %15 = zext u32 %14 to u64
    %16 = zext u32 %1 to u64
    %17 = call @func.0(%15, %16)
    ret %17
}
"#;

extern "C" fn repro_ext_add(a: u64, b: u64) -> u64 {
    a.wrapping_add(b)
}

#[test]
fn mir_tc_whnf_reduce_proj_iota_zext_load_callarg_roundtrip() {
    let module = trust_ir::parser::parse_module(REPRO_ZEXT_LOAD_CALLARG_TRUST_IR)
        .expect("repro module must parse");
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert("ext_add".to_string(), repro_ext_add as *const u8);
    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .compile_module_to_jit(&module, &externs)
        .expect("repro compile")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("repro_root")
        .expect("repro_root")
        .as_ptr();
    let rf: extern "C" fn(*const (u32, u32), u32) -> u64 = unsafe { std::mem::transmute(raw) };
    for (pair, rhs, expected) in [
        ((1u32, 7u32), 3u32, 10u64),
        ((1u32, 100u32), 5u32, 105u64),
        ((9u32, 0u32), 0u32, 0u64),
    ] {
        assert_eq!(
            rf(&pair, rhs),
            expected,
            "zext(load u32) must preserve the loaded value when used as a call argument"
        );
    }
    drop(buffer);
}
